26	const usageText = `Usage: wire <command> [arguments]
27	
28	Commands:
29	  start               Start the gateway (foreground)
30	  stop                Stop the running gateway
31	  status              Show backend status
32	  swap <backend> <model>  Hot-swap a backend's model
33	
34	Environment:
35	  WIRE_CONFIG         Config file path (default: ~/.config/wire/config.yaml)
