38	// Run dispatches CLI commands from the given argument slice (os.Args[1:]).
39	// It returns an exit code suitable for os.Exit.
40	func Run(args []string) int {
41		if err := dispatch(args); err != nil {
42			fmt.Fprintln(os.Stderr, "wire:", err)
43			return 1
44		}
45		return 0
46	}
