48	func dispatch(args []string) error {
49		if len(args) == 0 {
50			fmt.Print(usageText)
51			return nil
52		}
53		switch args[0] {
54		case "help", "--help", "-h":
55			fmt.Print(usageText)
56			return nil
57		case "start":
58			return runStart()
59		case "stop":
60			return runStop()
61		case "status":
62			return runStatus()
63		case "swap":
64			if len(args) < 3 {
65				return fmt.Errorf("swap requires <backend> and <model>\nUsage: wire swap <backend> <model>")
66			}
67			return runSwap(args[1], args[2])
68		default:
69			fmt.Print(usageText)
70			return fmt.Errorf("unknown command: %q", args[0])
71		}
72	}
