74	// pidFilePath returns the path to the PID file.
75	func pidFilePath() string {
76		if dir := os.Getenv("XDG_RUNTIME_DIR"); dir != "" {
77			return filepath.Join(dir, "wire.pid")
78		}
79		return "/tmp/wire.pid"
80	}
81	
82	// writePID creates the PID file exclusively, removing stale files where
83	// the recorded process is no longer alive.
84	func writePID(path string) error {
85		f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
86		if err != nil {
87			if !errors.Is(err, os.ErrExist) {
88				return fmt.Errorf("creating PID file %s: %w", path, err)
89			}
90			// File exists: check whether the recorded process is alive.
91			data, readErr := os.ReadFile(path)
92			if readErr != nil {
93				return fmt.Errorf("reading PID file: %w", readErr)
94			}
95			pid, parseErr := strconv.Atoi(strings.TrimSpace(string(data)))
96			if parseErr == nil {
97				proc, _ := os.FindProcess(pid)
98				if proc.Signal(syscall.Signal(0)) == nil {
99					return fmt.Errorf("wire is already running (pid %d)", pid)
100				}
101			}
102			// Stale file: remove and retry once.
103			slog.Info("removing stale PID file", "path", path)
104			if removeErr := os.Remove(path); removeErr != nil {
105				return fmt.Errorf("removing stale PID file: %w", removeErr)
106			}
107			f, err = os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0644)
108			if err != nil {
109				return fmt.Errorf("creating PID file after stale removal: %w", err)
110			}
111		}
112		defer f.Close()
113		_, err = fmt.Fprintf(f, "%d\n", os.Getpid())
114		return err
115	}
116	
117	// readPID reads the PID from the PID file.
118	func readPID(path string) (int, error) {
119		data, err := os.ReadFile(path)
120		if err != nil {
121			if errors.Is(err, os.ErrNotExist) {
122				return 0, fmt.Errorf("wire is not running (no PID file at %s)", path)
123			}
124			return 0, fmt.Errorf("reading PID file: %w", err)
125		}
126		pid, err := strconv.Atoi(strings.TrimSpace(string(data)))
127		if err != nil {
128			return 0, fmt.Errorf("invalid PID file: %w", err)
129		}
130		return pid, nil
131	}
132	
133	// configFilePath mirrors config.configPath so that cli can locate the file
134	// without modifying the config package.
135	func configFilePath() string {
136		if v := os.Getenv("WIRE_CONFIG"); v != "" {
137			return v
138		}
139		base := os.Getenv("XDG_CONFIG_HOME")
140		if base == "" {
141			home, _ := os.UserHomeDir()
142			base = filepath.Join(home, ".config")
143		}
144		return filepath.Join(base, "wire", "config.yaml")
145	}
146	
147	// writeConfigFile marshals cfg to YAML and atomically replaces the config file.
148	func writeConfigFile(cfg *config.Config) error {
149		path := configFilePath()
150		data, err := yaml.Marshal(cfg)
151		if err != nil {
152			return fmt.Errorf("marshaling config: %w", err)
153		}
154		tmp := path + ".tmp"
155		if err := os.WriteFile(tmp, data, 0644); err != nil {
156			return fmt.Errorf("writing config temp file: %w", err)
157		}
158		if err := os.Rename(tmp, path); err != nil {
159			os.Remove(tmp)
160			return fmt.Errorf("renaming config file: %w", err)
161		}
162		return nil
163	}
164	
165	// listenURL converts the listen address from config to an http:// URL.
166	func listenURL(listen string) string {
167		if strings.HasPrefix(listen, ":") {
168			return "http://localhost" + listen
169		}
170		return "http://" + listen
171	}
172	
173	func runStart() error {
174		cfg, err := config.Load()
175		if err != nil {
176			return fmt.Errorf("loading config: %w", err)
177		}
178	
179		pidPath := pidFilePath()
180		if err := writePID(pidPath); err != nil {
181			return err
182		}
183		defer os.Remove(pidPath)
184	
185		// bgCtx drives the process manager; cancelled only after gateway drains.
186		bgCtx, bgCancel := context.WithCancel(context.Background())
187		defer bgCancel()
188	
189		// shutCtx is cancelled by SIGTERM/SIGINT. Its Cause is the received signal.
190		shutCtx, stop := signal.NotifyContext(bgCtx, syscall.SIGTERM, syscall.SIGINT)
191		defer stop()
192	
193		// sighupCh receives SIGHUP for config reload.
194		sighupCh := make(chan os.Signal, 1)
195		signal.Notify(sighupCh, syscall.SIGHUP)
196		defer signal.Stop(sighupCh)
197	
198		mgr := process.New(cfg, slog.Default())
199		if err := mgr.Start(bgCtx); err != nil {
200			return fmt.Errorf("starting process manager: %w", err)
201		}
202	
203		gw := gateway.New(cfg, mgr, slog.Default())
204		gwErrCh := make(chan error, 1)
205		go func() { gwErrCh <- gw.ListenAndServe(shutCtx) }()
206	
207		slog.Info("wire ready", "listen", cfg.Listen)
208	
209		// swapMu serialises SIGHUP handling so overlapping reloads are dropped.
210		var swapMu sync.Mutex
211	
212		for {
213			select {
214			case err := <-gwErrCh:
215				bgCancel()
216				_ = mgr.Stop()
217				if err != nil {
218					return fmt.Errorf("gateway error: %w", err)
219				}
220				return nil
221	
222			case <-shutCtx.Done():
223				if cause := context.Cause(shutCtx); cause != nil {
224					slog.Info("shutting down", "cause", cause)
225				}
226				stop() // release signal resources early
227				// Wait for gateway to drain connections, then stop process manager.
228				if err := <-gwErrCh; err != nil {
229					slog.Error("gateway shutdown error", "error", err)
230				}
231				bgCancel()
232				return mgr.Stop()
233	
234			case <-sighupCh:
235				if !swapMu.TryLock() {
236					slog.Warn("SIGHUP received while swap in progress, ignoring")
237					continue
238				}
239				go func() {
240					defer swapMu.Unlock()
241					newCfg, loadErr := config.Load()
242					if loadErr != nil {
243						slog.Error("failed to reload config on SIGHUP", "error", loadErr)
244						return
245					}
246					for name, b := range newCfg.Backends {
247						oldB, ok := cfg.Backends[name]
248						if !ok || !b.IsManaged() {
249							continue
250						}
251						if b.Model != oldB.Model {
252							slog.Info("swapping backend model", "backend", name, "old", oldB.Model, "new", b.Model)
253							if swapErr := mgr.Swap(bgCtx, name, b.Model); swapErr != nil {
254								slog.Error("model swap failed", "backend", name, "error", swapErr)
255							}
256						}
257					}
258					cfg = newCfg
259				}()
260			}
261		}
262	}
263	
264	func runStop() error {
265		pidPath := pidFilePath()
266		pid, err := readPID(pidPath)
267		if err != nil {
268			return err
269		}
270		proc, err := os.FindProcess(pid)
271		if err != nil {
272			return fmt.Errorf("finding process %d: %w", pid, err)
273		}
274		if err := proc.Signal(syscall.SIGTERM); err != nil {
275			return fmt.Errorf("sending SIGTERM to pid %d: %w", pid, err)
276		}
277	
278		// Poll /proc/<pid> via kill -0 for up to 10 seconds.
279		deadline := time.Now().Add(10 * time.Second)
280		for time.Now().Before(deadline) {
281			if err := proc.Signal(syscall.Signal(0)); err != nil {
282				fmt.Printf("wire stopped (pid %d)\n", pid)
283				return nil
284			}
285			time.Sleep(200 * time.Millisecond)
286		}
287	
288		// Still alive: force kill.
289		_ = proc.Signal(syscall.SIGKILL)
290		fmt.Printf("wire force-killed (pid %d)\n", pid)
291		return nil
292	}
293	
294	func runStatus() error {
295		cfg, err := config.Load()
296		if err != nil {
297			return fmt.Errorf("loading config: %w", err)
298		}
299	
300		baseURL := listenURL(cfg.Listen)
301		client := &http.Client{Timeout: 5 * time.Second}
302	
303		healthResp, err := client.Get(baseURL + "/health")
304		if err != nil {
305			fmt.Println("wire is not running")
306			os.Exit(1)
307		}
308		defer healthResp.Body.Close()
309	
310		var healthBody struct {
311			Status string `json:"status"`
312		}
313		_ = json.NewDecoder(healthResp.Body).Decode(&healthBody)
314		overall := healthBody.Status
315		if overall == "" {
316			if healthResp.StatusCode == http.StatusOK {
317				overall = "healthy"
318			} else {
319				overall = "degraded"
320			}
321		}
322		fmt.Printf("wire: %s (%s)\n", overall, baseURL)
323	
324		modelsResp, err := client.Get(baseURL + "/v1/models")
325		if err != nil {
326			return nil
327		}
328		defer modelsResp.Body.Close()
329	
330		var modelsBody struct {
331			Data []struct {
332				ID string `json:"id"`
333			} `json:"data"`
334		}
335		if err := json.NewDecoder(modelsResp.Body).Decode(&modelsBody); err != nil {
336			return nil
337		}
338	
339		for _, m := range modelsBody.Data {
340			b, ok := cfg.Backends[m.ID]
341			model := m.ID
342			if ok {
343				if b.IsManaged() {
344					model = b.Model
345				} else {
346					model = b.URL
347				}
348			}
349			fmt.Printf("  %-14s %-40s %s\n", m.ID+":", model, overall)
350		}
351		return nil
352	}
353	
354	func runSwap(backend, model string) error {
355		cfg, err := config.Load()
356		if err != nil {
357			return fmt.Errorf("loading config: %w", err)
358		}
359	
360		b, ok := cfg.Backends[backend]
361		if !ok {
362			return fmt.Errorf("backend %q not found in config", backend)
363		}
364		if b.IsExternal() {
365			return fmt.Errorf("backend %q is external and cannot be swapped", backend)
366		}
367	
368		b.Model = model
369		cfg.Backends[backend] = b
370		if err := writeConfigFile(cfg); err != nil {
371			return err
372		}
373	
374		pidPath := pidFilePath()
375		pid, err := readPID(pidPath)
376		if err != nil {
377			return err
378		}
379		proc, err := os.FindProcess(pid)
380		if err != nil {
381			return fmt.Errorf("finding process: %w", err)
382		}
383		if err := proc.Signal(syscall.SIGHUP); err != nil {
384			return fmt.Errorf("sending SIGHUP to pid %d: %w", pid, err)
385		}
386	
387		fmt.Printf("sent reload signal to wire (pid %d); run 'wire status' to check progress\n", pid)
388		return nil
389	}
